import {examples} from './examples.js';
import {renderAnnotatedSentence,clauseAnnotations} from './annotations.js';
import {splitSentences,validateImport,makePrompt} from './engine.js';
const $=id=>document.getElementById(id);
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const defaultText='Introduction\n\n'+examples.slice(0,3).map(a=>a.sentence).join(' ')+'\n\n'+examples.slice(3,5).map(a=>a.sentence).join(' ')+'\n\n'+examples.slice(5).map(a=>a.sentence).join(' ');
const key='sentence-document:v2';
let state={text:defaultText,analyses:structuredClone(examples),fontSize:22,showAnnotations:true,showClauses:true},toastTimer;
const normalize=s=>s.replace(/[’‘]/g,"'").replace(/[“”]/g,'"').replace(/\s+/g,' ').trim();
const labels={subject:'主语',predicate:'谓语',object:'宾语',complement:'表语 / 补语'};
function toast(message){$('toast').textContent=message;$('toast').hidden=false;clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('toast').hidden=true,3200)}
function save(){try{localStorage.setItem(key,JSON.stringify(state));$('save-status').textContent='已保存在浏览器'}catch{$('save-status').textContent='当前浏览器无法保存'}}
function annotation(text,role,label){const spaces=text.match(/^(\s*)([\s\S]*?)(\s*)$/);return esc(spaces[1])+`<mark class="annotation ${role}" title="${esc(label)}" aria-label="${esc(label+'：'+spaces[2])}">${esc(spaces[2])}</mark>`+esc(spaces[3])}
function renderSentence(sentence){const a=state.analyses.find(a=>normalize(a.sentence)===normalize(sentence)&&!a.basic);return {html:renderAnnotatedSentence(sentence,a),annotated:!!a}}
function render(){let total=0,annotated=0;const paragraphs=state.text.split(/\n\s*\n/).map(p=>p.trim()).filter(Boolean);const html=paragraphs.map((paragraph,index)=>{const clean=paragraph.replace(/^#{1,6}\s+/,'').replace(/\[([^\]]+)\]\([^)]*\)/g,'$1');const isHeading=/^#{1,6}\s/.test(paragraph)||(paragraphs.length>1&&index===0&&clean.length<80&&clean.split(/\s+/).length<=10&&!/[.!?。！？]/.test(clean)&&!clean.includes('\n'));if(isHeading)return `<${index===0?'h1':'h2'}>${esc(clean)}</${index===0?'h1':'h2'}>`;const source=clean.replace(/\s*\n\s*/g,' ');const sentences=splitSentences(source);let cursor=0;let body='';for(const sentence of sentences){const at=source.indexOf(sentence,cursor);if(at<0){body+=esc(source.slice(cursor));cursor=source.length;break}body+=esc(source.slice(cursor,at));const result=renderSentence(sentence);body+=result.html;cursor=at+sentence.length;total++;if(result.annotated)annotated++}body+=esc(source.slice(cursor));return `<p>${body}</p>`}).join('');$('document-content').innerHTML=html||'<p class="empty-document">Paste a passage. Read it at your own pace.</p>';$('annotation-status').textContent=total?`${annotated} / ${total} 句已标注主干`:'等待原文';$('reading-hint').textContent=total&&annotated<total?'未标注的句子保留原文。把文章发给我，再导入标注文件即可。':'实线标主句主干，虚线标从句内部成分。括号圈出边界，小字说明它接在哪里。';document.documentElement.style.setProperty('--font-size',state.fontSize+'px');$('font-size').textContent=state.fontSize;$('smaller-button').disabled=state.fontSize<=16;$('larger-button').disabled=state.fontSize>=30;$('annotations-toggle').checked=state.showAnnotations;document.body.classList.toggle('no-annotations',!state.showAnnotations);$('clauses-toggle').checked=state.showClauses!==false;document.body.classList.toggle('no-clauses',state.showClauses===false)}
function showDialog(id){$(id).showModal()}
function counter(){$('character-count').textContent=$('source-input').value.length.toLocaleString()+' / 20,000'}
$('edit-button').addEventListener('click',()=>{$('source-input').value=state.text;$('edit-error').hidden=true;counter();showDialog('edit-dialog')});
$('source-input').addEventListener('input',counter);
$('apply-button').addEventListener('click',()=>{const text=$('source-input').value.trim();if(!text){$('edit-error').textContent='请先粘贴英文原文。';$('edit-error').hidden=false;return}state.text=text;render();save();$('edit-dialog').close();toast('已按原文段落排版')});
$('source-input').addEventListener('keydown',e=>{if((e.metaKey||e.ctrlKey)&&e.key==='Enter')$('apply-button').click()});
$('clauses-toggle').addEventListener('change',e=>{state.showClauses=e.target.checked;render();save()});
$('annotations-toggle').addEventListener('change',e=>{state.showAnnotations=e.target.checked;render();save()});
$('smaller-button').addEventListener('click',()=>{state.fontSize=Math.max(16,state.fontSize-2);render();save()});
$('larger-button').addEventListener('click',()=>{state.fontSize=Math.min(30,state.fontSize+2);render();save()});
$('example-button').addEventListener('click',()=>{state.text=defaultText;state.analyses=structuredClone(examples);render();save();toast('已载入你的示例文章')});
$('import-button').addEventListener('click',()=>showDialog('import-dialog'));
$('print-button').addEventListener('click',()=>window.print());
$('export-button').addEventListener('click',()=>{const data={version:1,documentText:state.text,analyses:state.analyses.map(a=>{const i=examples.findIndex(e=>normalize(e.sentence)===normalize(a.sentence));return {...a,clauses:a.clauses||(i>=0?clauseAnnotations[i]:[])}})};const blob=new Blob([JSON.stringify(data,null,2)],{type:'application/json;charset=utf-8'});const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='句读-文章与主干标注.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('已导出文章与标注，可在「导入标注」恢复')});
$('confirm-import').addEventListener('click',()=>{try{const raw=$('import-input').value;const imported=validateImport(raw);if(imported.documentText!==undefined&&(typeof imported.documentText!=='string'||imported.documentText.length>20000))throw Error('documentText 需要是 20,000 字符以内的原文。');const hasCurrentMatches=imported.analyses.some(a=>normalize(state.text).includes(normalize(a.sentence)));state.analyses=imported.analyses;state.text=imported.documentText||(hasCurrentMatches?state.text:imported.analyses.map(a=>a.sentence).join(' '));render();save();$('import-dialog').close();$('import-input').value='';$('import-error').hidden=true;toast('主干标注已应用到原文')}catch(e){$('import-error').textContent=e.message;$('import-error').hidden=false}});
$('import-file').addEventListener('change',async e=>{const file=e.target.files[0];if(!file)return;try{if(file.size>1500000)throw Error('文件超过 1.5 MB，请分批导入。');$('import-input').value=await file.text();$('import-error').hidden=true}catch(error){$('import-error').textContent=error.message;$('import-error').hidden=false}e.target.value=''});
$('copy-prompt').addEventListener('click',async()=>{const prompt=makePrompt(state.text)+'\n额外要求：本页面只在完整文章里标注主句主干。请把原文完整保存在最外层 documentText 字段；每句额外包含 clauses 数组，元素为 {text:完整连续的从句或短语原文,label:中文名称,relation:修饰或依附对象,kind:clause或phrase,parts:[{text:从句内成分原文,role:subject或predicate或object或complement,label:中文语法名称}]}。clause 只用于含限定谓语的从句；不定式、分词和同位补充用 phrase。所有 text 必须与原句中的片段完全一致。原文，保留标题与段落空行。从句、插入语、状语等的 fragments.main 必须设为 false，主句主语、谓语、宾语、表语及必要补语设为 true。';try{await navigator.clipboard.writeText(prompt);toast('已复制，粘贴给我即可')}catch{toast('复制失败，请直接把原文发到对话里')}});
for(const button of document.querySelectorAll('[data-close]'))button.addEventListener('click',()=>button.closest('dialog').close());
for(const dialog of document.querySelectorAll('dialog'))dialog.addEventListener('click',e=>{if(e.target===dialog){const r=dialog.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)dialog.close()}});
try{const previous=JSON.parse(localStorage.getItem(key));if(previous&&typeof previous.text==='string'&&previous.text.length<=20000){validateImport({version:1,analyses:previous.analyses});state={...previous,fontSize:Math.max(16,Math.min(30,Number(previous.fontSize)||22)),showAnnotations:previous.showAnnotations!==false,showClauses:previous.showClauses!==false}}}catch{}
render();
